/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length === 2) {
    const [str1, str2] = lines;

    console.log(getIntersections(str1, str2));

    lines.length = 0;
  }
});

function getIntersections(str1, str2) {
  const set1 = new Set(str1);
  const set2 = new Set(str2);

  return [...set1]
    .filter((c) => set2.has(c))
    .sort()
    .join("");
}

